-- ARMS by EDGE10 — Моніторинг навантаження та відновлення
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'edge10group.com' OR LOWER(`name`) = LOWER('ARMS by EDGE10'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'ARMS by EDGE10', NULL, 'https://edge10group.com', NULL, NULL, 'ARMS від EDGE10 — система керування даними спортсменів для ліг, організацій і команд: збір, аналіз, візуалізація й захист даних про здоров''я, продуктивність і фізичні тести; перша загальнолігова система медичних записів.', 'ARMS by EDGE10 is an athlete data management system for leagues, organizations and teams: collecting, analyzing, visualizing and securing health, performance and physical testing data; the first league-wide records system.', 'ARMS (Athlete Records Management System) від EDGE10 Group — система, створена практиками для практиків. Вона стала першою у світі загальнолігововою системою ведення записів про спортсменів. Платформа збирає, аналізує й візуалізує дані спортсменів, допомагаючи лігам, спортивним організаціям і командам по-новому використовувати інформацію для захисту здоров''я атлетів і покращення їхніх результатів. Продукти поділено на напрями: здоров''я, продуктивність і фізичне тестування. Особливу увагу приділено безпеці даних. Система працює з клієнтами в Північній Америці, Європі, Австралазії, Індії та Японії, а на сайті є кейси клієнтів і блог.', 'ARMS (Athlete Records Management System) by EDGE10 Group is built by practitioners for practitioners. It was the world''s first league-wide athlete records management system. The platform collects, analyzes and visualizes athlete data, helping leagues, sports organizations and teams use information in new ways to protect athletes'' health and enhance performance. Products are grouped into health, performance and physical testing. Data security is a particular focus. The system serves clients in North America, Europe, Australasia, India and Japan, and the site has client stories and a blog.', 'Медичні записи спортсменів
Дані про продуктивність
Фізичне тестування
Візуалізація й аналітика
Рішення для ліг і команд
Захист даних', 'Athlete medical records
Performance data
Physical testing
Visualization and analytics
Solutions for leagues and teams
Data security', 'Професійні ліги, спортивні організації та команди, медичний і тренерський персонал.', 'Professional leagues, sports organizations and teams, medical and coaching staff.', 'web', 'course', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'edge10group.com' OR LOWER(`name`) = LOWER('ARMS by EDGE10')) ORDER BY `id` LIMIT 1);
