INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'ARMS (Athlete Records Management System) by EDGE10 Group is built by practitioners for practitioners. It was the world''s first league-wide athlete records management system. The platform collects, analyzes and visualizes athlete data, helping leagues, sports organizations and teams use information in new ways to protect athletes'' health and enhance performance. Products are grouped into health, performance and physical testing. Data security is a particular focus. The system serves clients in North America, Europe, Australasia, India and Japan, and the site has client stories and a blog.', 'manual' FROM DUAL WHERE @new = 1;
