-- Athlete Blood Test — Моніторинг навантаження та відновлення
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'athletebloodtest.com' OR LOWER(`name`) = LOWER('Athlete Blood Test'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Athlete Blood Test', NULL, 'https://www.athletebloodtest.com', NULL, NULL, 'Athlete Blood Test — індивідуальне тестування біомаркерів крові для спортсменів: панелі від Bronze для швидкої перевірки перед стартами, звіти, які переглядає живий експерт, і рекомендації щодо харчування, відновлення й тренувань.', 'Athlete Blood Test offers individually tailored blood biomarker testing for athletes: panels from Bronze for quick pre-competition check-ins, reports reviewed by a human expert and advice on nutrition, recovery and training.', 'Athlete Blood Test пропонує аналіз біомаркерів крові, орієнтований саме на спортсменів, щоб допомогти налаштувати харчування, відновлення, тренування й результати. Головна відмінність — кожен звіт переглядає справжній експерт, поєднуючи розумну аналітику з тренерським досвідом, тож рекомендації залишаються персональними, практичними й узгодженими з вашим тренувальним шляхом. Доступні різні панелі тестів: наприклад, Bronze розрахована на швидкі перевірки продуктивності й налаштування перед змаганнями та аналізує ключові системи, що відповідають за енергію й гідратацію. Є рішення для професійних команд, корпоративних атлетів, база знань і консультації дієтолога.', 'Athlete Blood Test provides athlete-focused blood biomarker testing to help dial in nutrition, recovery, training and performance. The key difference is that every report is reviewed by a real human expert who blends smart analytics with coaching insight, so recommendations stay personal, practical and aligned with your training journey. Several test panels are available: for example, Bronze is designed for quick performance check-ins and pre-competition tune-ups and analyzes core systems behind energy and hydration. There are solutions for pro teams and corporate athletes, a knowledge hub and dietitian consultations.', 'Аналіз крові для спортсменів
Панелі тестів різного рівня
Звіти з переглядом експерта
Рекомендації щодо харчування й відновлення
Рішення для професійних команд
Консультації дієтолога', 'Blood testing for athletes
Panels at several levels
Expert-reviewed reports
Nutrition and recovery advice
Pro team solutions
Dietitian consultations', 'Спортсмени на витривалість, професійні команди й активні люди.', 'Endurance athletes, pro teams and active people.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
