SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'athletemonitoring.com' OR LOWER(`name`) = LOWER('AthleteMonitoring'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'AthleteMonitoring', NULL, 'https://www.athletemonitoring.com', NULL, NULL, 'AthleteMonitoring — гнучка й доступна система управління спортсменами: моніторинг самопочуття, керування навантаженням, трекер менструального циклу, медичні записи, тестування, конструктор тренувань і опитування.', 'AthleteMonitoring is a flexible, affordable athlete management system: wellness monitoring, workload management, a menstrual cycle tracker, medical records, testing, a workout builder and questionnaires.', 'AthleteMonitoring допомагає покращувати результати, запобігати травмам і керувати всіма даними спортсменів у простій і бюджетній системі. Модулі охоплюють моніторинг самопочуття, керування тренувальним навантаженням, трекер менструального циклу, електронні медичні записи, медичний нагляд і облік травм і захворювань, тестування й оцінювання, конструктор тренувань, онлайн-опитувальники, обмін файлами й медіа, а також інтеграції. Рішення розраховане на олімпійські комітети й міжнародні федерації, спортивні ліги й федерації, елітні команди та клуби, коледжі й університети, медицину, виконавські мистецтва й дослідницькі установи. Є демо, кейси, вебінари й дослідження.', 'AthleteMonitoring helps optimize performance, prevent injuries and manage all athlete data in a simple, budget-friendly system. Modules cover wellness monitoring, training workload management, a menstrual cycle tracker, electronic health records, health surveillance and injury and illness tracking, testing and assessment, a workout builder, online questionnaires, file and media sharing, and integrations. It is designed for Olympic committees and international federations, sports leagues and federations, elite teams and clubs, colleges and universities, healthcare, performing arts and research institutions. Demos, case studies, webinars and research are available.', 'Моніторинг самопочуття
Керування навантаженням
Трекер менструального циклу
Медичні записи й облік травм
Тестування й опитування
Конструктор тренувань', 'Wellness monitoring
Workload management
Menstrual cycle tracker
Medical records and injury tracking
Testing and questionnaires
Workout builder', 'Олімпійські комітети, федерації, професійні та університетські команди.', 'Olympic committees, federations, professional and college teams.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
