INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Breathwrk', NULL, 'https://www.breathwrk.com', NULL, NULL, 'Breathwrk — застосунок дихальних вправ і занять, що допомагають заспокоїтися, зосередитися, підвищити витривалість і швидше заснути; тепер частина Peloton і безплатний для учасників Peloton All-Access, Guide та App+.', 'Breathwrk is a breathing exercise and class app that helps you calm down, focus, increase stamina and fall asleep faster; now part of Peloton and free for Peloton All-Access, Guide and App+ members.', 'Breathwrk допомагає розкрити ментальний і фізичний потенціал за допомогою дихальних вправ і занять. Окремі практики спрямовані на те, щоб заспокоїтися, зосередитися, підвищити витривалість або швидко заснути. Тепер Breathwrk є частиною Peloton і продовжує працювати в США, Канаді, Мексиці, Великій Британії, Австралії та ЄС. Для учасників Peloton з тарифами All-Access, Guide і App+ застосунок безплатний, а учасникам AppOne і Strength+ потрібно оформити окрему підписку; вхід здійснюється через обліковий запис Peloton. Окремо доступні Breathwrk Pro, рішення для бізнесу та сертифікація з дихальних практик, а також блог і наукові матеріали.', 'Breathwrk helps unlock your mental and physical potential with breathing exercises and classes. Separate practices aim to help you calm down, focus, increase stamina or fall asleep quickly. Breathwrk is now part of Peloton and remains available in the US, Canada, Mexico, the UK, Australia and the EU. For Peloton All-Access, Guide and App+ members the app is free, while AppOne and Strength+ members need a separate subscription; sign-in uses your Peloton account. Breathwrk Pro, business solutions and breathwork certification are also available, along with a blog and science resources.', 'Дихальні вправи й заняття
Для спокою, фокусу, витривалості й сну
