-- CORE — Моніторинг навантаження та відновлення
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'corebodytemp.com' OR LOWER(`name`) = LOWER('CORE'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'CORE', NULL, 'https://corebodytemp.com', NULL, NULL, 'CORE — перший неінвазивний сенсор, що безперервно й точно вимірює температуру ядра тіла в реальних умовах: допомагає безпечно проводити тренування в спеку, керувати перегрівом і зберігати потужність і темп.', 'CORE is the first non-invasive sensor to continuously and accurately measure core body temperature in real life: it helps run heat training safely, manage overheating and preserve power and pace.', 'CORE — носимий сенсор для спортсменів, які серйозно ставляться до результатів, здоров''я та самопочуття. Він неінвазивно й безперервно вимірює температуру ядра тіла в реальних умовах. Коли під час інтенсивного навантаження температура ядра зростає, потужність і темп падають, тому сильні тренери й атлети використовують CORE для тренувань у спеку — щоб безпечно адаптуватися й оптимізувати результати за принципом «тренуйся в спеку — змагайся прохолодним». Пристрій застосовують у спорті, для безпеки працівників і в дослідженнях. Модель CORE 2 доступна з 30-денним пробним періодом без ризику; на сайті є навчальні матеріали, підтримка та блог.', 'CORE is a wearable sensor for athletes serious about their performance, health and wellbeing. It non-invasively and continuously measures core body temperature under real-life conditions. When core temperature rises during intense exercise, power and pace decline, so top coaches and athletes use CORE for heat training — to adapt safely and optimize performance on the train hot, race cool principle. The device is used in sport, worker safety and research. CORE 2 comes with a 30-day risk-free trial, and the site has education, support and a blog.', 'Безперервне вимірювання температури ядра
Неінвазивний носимий сенсор
Тренування в спеку
Безпека й дослідження
30 днів на пробу', 'Continuous core temperature
Non-invasive wearable
Heat training
Safety and research
30-day trial', 'Спортсмени на витривалість, тренери, дослідники й фахівці з безпеки праці.', 'Endurance athletes, coaches, researchers and safety professionals.', 'mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
