-- COSMED — Моніторинг навантаження та відновлення
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'cosmed.com' OR LOWER(`name`) = LOWER('COSMED'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'COSMED', NULL, 'https://www.cosmed.com', NULL, NULL, 'COSMED — обладнання для метаболічної та кардіопульмональної діагностики: кардіопульмональні навантажувальні тести, непряма калориметрія, спірометрія, склад тіла, ЕКГ, ергометри й ПЗ для спортивної науки та медицини.', 'COSMED makes metabolic and cardiopulmonary diagnostics equipment: cardiopulmonary exercise testing, indirect calorimetry, spirometry, body composition, ECG, ergometers and software for sports science and medicine.', 'COSMED — виробник обладнання для метаболічної та кардіопульмональної діагностики, яке використовують у медицині й спортивній науці. Лінійка охоплює системи кардіопульмонального навантажувального тестування (CPET) для оцінки VO2max і порогів, непряму калориметрію для визначення обміну речовин, тести функції легень і спірометрію, аналізатори складу тіла, ЕКГ, ергометри, аксесуари та програмне забезпечення. Новий метаболічний монітор Q-NRG Max розширює можливості непрямої калориметрії. Рішення застосовують у пульмонології, кардіології, педіатрії, неонатології, спортивній науці, нутриціології, реанімації, реабілітації, дослідженнях продуктивності людини й довголіття. На сайті є настанови, білі книги, вебінари й відео.', 'COSMED manufactures metabolic and cardiopulmonary diagnostics equipment used in medicine and sports science. The lineup covers cardiopulmonary exercise testing (CPET) systems for assessing VO2max and thresholds, indirect calorimetry for metabolism, pulmonary function tests and spirometry, body composition analyzers, ECG, ergometers, accessories and software. The new Q-NRG Max metabolic monitor expands indirect calorimetry capabilities. Applications include pulmonology, cardiology, pediatrics, neonatology, sports science, nutrition, critical care, rehabilitation, human performance and longevity research. The site has guidelines, white papers, webinars and videos.', 'Кардіопульмональні навантажувальні тести
Непряма калориметрія
Спірометрія
Аналіз складу тіла
Ергометри й ЕКГ
Програмне забезпечення', 'Cardiopulmonary exercise testing
Indirect calorimetry
Spirometry
Body composition analysis
Ergometers and ECG
Software', 'Спортивні лабораторії, клініки, дослідники та центри продуктивності.', 'Sports labs, clinics, researchers and performance centers.', 'desktop', 'course', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
