-- Epicore Biosystems — Моніторинг навантаження та відновлення
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'epicorebiosystems.com' OR LOWER(`name`) = LOWER('Epicore Biosystems'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Epicore Biosystems', NULL, 'https://epicorebiosystems.com', NULL, NULL, 'Epicore Biosystems — носимі біосенсори, що аналізують піт у реальному часі: гідратація, втрати електролітів і ризик теплового стресу для спорту й фітнесу, промислової безпеки та клінічних досліджень. Є публікації.', 'Epicore Biosystems makes wearable biosensors that analyze sweat in real time: hydration, electrolyte loss and heat stress risk for sports and fitness, industrial safety and clinical research.', 'Epicore Biosystems розробляє «біоносимі» пристрої, що допомагають людям краще працювати й тренуватися. Кожна крапля поту містить багато біомаркерів — електроліти, метаболіти, поживні речовини, білки, токсини та інше. Рішення компанії вимірюють гідратацію, харчування, стрес і показники здоров''я, аналізуючи піт разом з іншими фізіологічними даними. У спорті й фітнесі це допомагає підбирати стратегію пиття й запобігати перегріву, у промисловості — забезпечувати безпеку працівників завдяки втручанням у реальному часі, а в клінічних дослідженнях — збирати нові дані. На сайті є дослідження, публікації, новини, блог і вхід для клієнтів.', 'Epicore Biosystems develops biowearables that help people work and train better. Every drop of sweat contains many biomarkers — electrolytes, metabolites, nutrients, proteins, toxins and more. The company''s solutions measure hydration, nutrition, stress and health-related biomarkers by analyzing sweat together with other physiological data. In sports and fitness this helps tailor hydration strategy and prevent overheating, in industry it keeps workers safe through real-time interventions, and in clinical research it produces new data. The site has research, publications, news, a blog and a customer login.', 'Аналіз поту в реальному часі
Гідратація й електроліти
Ризик теплового стресу
Спорт, промисловість і дослідження
Наукові публікації', 'Real-time sweat analysis
Hydration and electrolytes
Heat stress risk
Sport, industry and research
Scientific publications', 'Спортсмени й команди, промислові компанії та дослідники.', 'Athletes and teams, industrial companies and researchers.', 'mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
