SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'fit3d.com' OR LOWER(`name`) = LOWER('Fit3D'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Fit3D', NULL, 'https://www.fit3d.com', NULL, NULL, 'Fit3D — технологія 3D-сканування тіла для фітнес-фахівців: точні виміри, 3D-склад тіла, оцінки добробуту, повнокольорові скани, сканер SNAP і нове сканування без апаратури для утримання клієнтів і доходу.', 'Fit3D offers 3D body scanning technology for fitness professionals: accurate measurements, 3D body composition, wellness assessments, full-color scans, the SNAP scanner and new hardware-free scanning to boost retention and revenue.', 'Fit3D пропонує 3D-сканування тіла для точних вимірювань, відстеження фітнес-прогресу й оцінки здоров''я. Клієнти отримують повнокольорові 3D-скани, дані про склад тіла та велнес-оцінки, які наочно показують зміни. Компанія розвиває новий підхід — сканування з тією самою точністю, але без окремої машини, а також пропонує сканер SNAP і програмне забезпечення Fit3D. Рішення допомагають фітнес-клубам і студіям, центрам контурної пластики та програмам схуднення підвищувати утримання учасників і дохід. На сайті є варіанти цін, історії клієнтів, блог, опис досвіду кінцевого користувача, підтримка й запит на демонстрацію.', 'Fit3D provides 3D body scanning for accurate measurements, fitness tracking and health assessments. Clients get full-color 3D scans, body composition data and wellness assessments that show changes clearly. The company is developing a new approach — the same accuracy without a dedicated machine — and also offers the SNAP scanner and Fit3D software. Solutions help fitness clubs and studios, body contouring centers and weight loss programs increase member retention and revenue. The site has pricing options, client wins, a blog, the end-user experience, support and demo requests.', '3D-сканування тіла
