SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'fitogether.com' OR LOWER(`name`) = LOWER('Fitogether'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Fitogether', NULL, 'https://www.fitogether.com', NULL, NULL, 'Fitogether — GPS-трекінг продуктивності для футболу з технологією RTK GNSS, що в рази точніше визначає позицію гравця: фіксує секунди руху, метри дистанції й відсотки швидкості, які вирішують результат.', 'Fitogether offers GPS performance tracking for football with RTK GNSS technology that pinpoints player position far more accurately, capturing the seconds, metres and percentage points of speed that decide results.', 'Fitogether виходить з того, що на високому рівні перемогу визначають деталі: секунда руху, метр дистанції чи відсоток різниці у швидкості. Компанія фіксує дані, які пропускають інші. Ключова технологія — RTK (Real-Time Kinematic) GNSS, що значно підвищує точність визначення позиції гравця порівняно зі звичайним GPS. Носимі трекери збирають показники дистанції, швидкості, прискорень і навантаження, а програмне забезпечення допомагає тренерам і спортивним науковцям аналізувати їх і керувати підготовкою. Fitogether представлялася на виставці глобальних інновацій у Музеї FIFA; на сайті доступний каталог продуктів кількома мовами.', 'Fitogether starts from the idea that at the top level, details decide victory: one second of movement, one metre of distance or a 1% difference in speed. The company captures the data others miss. Its key technology is RTK (Real-Time Kinematic) GNSS, which greatly improves player positioning accuracy compared with standard GPS. Wearable trackers collect distance, speed, acceleration and load metrics, and the software helps coaches and sports scientists analyze them and manage training. Fitogether has been shown at the FIFA Museum''s Global Innovation Exhibition, and the site offers a product catalog in several languages.', 'Технологія RTK GNSS
Висока точність позиціонування
Дистанція, швидкість і прискорення
Аналіз навантаження
Каталог продуктів кількома мовами', 'RTK GNSS technology
High positioning accuracy
Distance, speed and acceleration
Load analysis
Multilingual product catalog', 'Професійні футбольні клуби, академії та спортивні науковці.', 'Professional football clubs, academies and sports scientists.', 'mobile,web', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
