SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'hexoskin.com' OR LOWER(`name`) = LOWER('Hexoskin'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Hexoskin', NULL, 'https://hexoskin.com', NULL, NULL, 'Hexoskin — клінічно валідовані розумні футболки, що безперервно вимірюють ЕКГ, ВСР, дихання, активність і сон; зручний одяг, який можна прати, платформа даних, застосунки й Astroskin для досліджень і навіть космосу.', 'Hexoskin makes clinically validated smart shirts that continuously measure ECG, HRV, breathing, activity and sleep: comfortable washable garments, a data platform, apps and Astroskin for research and even space.', 'Hexoskin створює розумний одяг, що безперервно відстежує п''ять життєвих показників. Футболки зручні, їх можна прати, а вбудовані сенсори фіксують ЕКГ, варіабельність серцевого ритму, дихання, активність і сон. Дані передаються на платформу Hexoskin і в застосунки, де їх можна аналізувати для оцінки навантаження, відновлення та здоров''я. Пристрої клінічно валідовані й застосовуються в клінічних дослідженнях, охороні здоров''я, оборонних структурах і рятувальних службах, а версія Astroskin використовується навіть у космосі. Є ProShirt, гід із розмірів, документація для розробників, наукова література й розділ про сон.', 'Hexoskin builds smart clothing that continuously monitors five vital signs. The shirts are comfortable and washable, and built-in sensors record ECG, heart rate variability, breathing, activity and sleep. Data flow to the Hexoskin platform and apps for analyzing load, recovery and health. The devices are clinically validated and used in clinical research, healthcare, defense and first responders, and the Astroskin version is even used in space. There is a ProShirt, a sizing guide, developer documentation, scientific literature and a sleep section.', 'Безперервна ЕКГ і ВСР
