INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Hyperice', NULL, 'https://hyperice.com', NULL, NULL, 'Hyperice — професійні засоби відновлення: масажні пістолети Hypervolt, компресійні системи Normatec, пристрої з теплом і вібрацією для колін і стоп (зокрема з Nike), контрастна терапія; для атлетів і всіх, хто рухається.', 'Hyperice makes professional-grade recovery tools: Hypervolt massage guns, Normatec compression systems, heat and vibration devices for knees and feet (including with Nike) and contrast therapy, for athletes and everyday movers.', 'Hyperice створює технології відновлення та добробуту професійного рівня, якими користуються як елітні атлети, так і звичайні люди. Лінійка включає масажні пістолети Hypervolt (зокрема Hypervolt 3 Pro з шістьма швидкостями й п''ятьма насадками), компресійні системи Normatec для ніг і стегон, пристрої з теплом і вібрацією для колін і плечей, засоби контрастної терапії, а також спільну з Nike розробку Air Zoom Hyperslide для відновлення стоп. Пристрої допомагають швидше відновлюватися після тренувань і зменшувати напругу в м''язах. Продукцію можна оплатити з FSA/HSA у США, а від певної суми доставка безплатна.', 'Hyperice builds professional-grade recovery and wellness technology used by elite athletes and everyday people alike. The lineup includes Hypervolt massage guns (such as the Hypervolt 3 Pro with six speeds and five head attachments), Normatec compression systems for legs and hips, heat and vibration devices for knees and shoulders, contrast therapy tools and the Nike Air Zoom Hyperslide co-developed with Nike for foot recovery. The devices help you recover faster after training and reduce muscle tension. Products are FSA/HSA eligible in the US, with free shipping above a certain amount.', 'Масажні пістолети Hypervolt
Компресійні системи Normatec
Тепло й вібрація для суглобів
Контрастна терапія
