-- Hytro — Моніторинг навантаження та відновлення
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'hytro.com' OR LOWER(`name`) = LOWER('Hytro'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Hytro', NULL, 'https://hytro.com', NULL, NULL, 'Hytro — носимий одяг для тренувань з обмеженням кровотоку (BFR): шорти й футболки, що відкривають переваги BFR до, під час і після тренування, протоколи для видів спорту, навчання й сертифікація з BFR.', 'Hytro makes wearable blood flow restriction (BFR) training apparel: shorts and tees that unlock BFR benefits before, during and after exercise, sport-specific protocols and BFR education and certification.', 'Hytro створює носимі рішення для тренувань з обмеженням кровотоку (BFR), що дозволяють отримувати їхні переваги до, під час і після вправ. Замість окремих манжет компанія пропонує шорти й футболки для чоловіків і жінок. Продукція розрахована на багато видів спорту — бейсбол, баскетбол, велоспорт, американський футбол, хокей, регбі, футбол, зокрема жіночий. Для професійних і університетських команд є окремі рішення та можливість спробувати Hytro. Розділ освіти містить сертифікацію з BFR, протоколи використання, дослідження й інструкції. У Північній Америці продукцію можна оплатити з HSA/FSA. Це зручно для тренувань у залі та вдома.', 'Hytro builds wearable blood flow restriction (BFR) solutions that unlock its benefits before, during and after exercise. Instead of separate cuffs, the company offers shorts and T-shirts for men and women. The products serve many sports — baseball, basketball, cycling, football, ice hockey, rugby and soccer, including women''s soccer. Professional and college teams get dedicated solutions and can trial Hytro. The education section includes BFR certification, usage protocols, research and how-to guides. In North America the products can be paid for with HSA/FSA funds. It is convenient for gym and home training.', 'Носимий одяг для BFR
Шорти й футболки для чоловіків і жінок
Протоколи для різних видів спорту
Сертифікація з BFR
Рішення для команд', 'Wearable BFR apparel
Shorts and tees for men and women
Sport-specific protocols
BFR certification
Team solutions', 'Спортсмени, команди, тренери з фізпідготовки й фізіотерапевти.', 'Athletes, teams, strength coaches and physiotherapists.', 'mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
