SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'inbodyusa.com' OR LOWER(`name`) = LOWER('InBody'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'InBody', NULL, 'https://inbodyusa.com', NULL, NULL, 'InBody — аналізатори складу тіла на основі технології біоімпедансу для медичних, фітнес- і нутриціологічних фахівців: моделі від InBody 270S до 970S, InBody для дому, тонометри, динамометр і ростоміри.', 'InBody makes bioimpedance body composition analyzers for medical, fitness and nutrition professionals: models from InBody 270S to 970S, InBody at Home, blood pressure monitors, a grip dynamometer and stadiometers.', 'InBody виробляє пристрої для аналізу складу тіла, призначені для медичних, фітнес- і нутриціологічних фахівців. Вони використовують технологію біоелектричного імпедансного аналізу (BIA) і показують не лише вагу, а й м''язову масу, жир і воду в організмі. Лінійка включає моделі InBody 270S, 380, 580, 770S, 970S і BWA 2.0S для професійного використання, а також InBody для дому. Тонометри BPBIO інтегруються з даними InBody, а спеціалізовані пристрої — динамометр InGrip FRA 510S і ростоміри — доповнюють екосистему. Для закладів доступне фінансування. Рішення допомагають тренерам і лікарям об''єктивно відстежувати прогрес клієнтів.', 'InBody manufactures body composition analysis devices designed for medical, fitness and nutrition professionals. They use bioelectrical impedance analysis (BIA) technology and show not just weight but muscle mass, fat and body water. The lineup includes the InBody 270S, 380, 580, 770S, 970S and BWA 2.0S for professional use, plus InBody at Home. BPBIO blood pressure monitors integrate with InBody data, and specialized devices — the InGrip FRA 510S dynamometer and stadiometers — complete the ecosystem. Financing is available for facilities. The solutions help trainers and clinicians track client progress objectively.', 'Аналіз складу тіла BIA
Професійні моделі від 270S до 970S
InBody для дому
Тонометри BPBIO
Динамометр і ростоміри
Фінансування', 'BIA body composition analysis
