SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'insidetracker.com' OR LOWER(`name`) = LOWER('InsideTracker'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'InsideTracker', NULL, 'https://www.insidetracker.com', NULL, NULL, 'InsideTracker — точний аналіз біомаркерів крові та персональні рекомендації щодо харчування, вправ і добавок для покращення здоров''я й фізичної форми; AI-помічник Terra, план дій і рішення для компаній.', 'InsideTracker offers accurate blood biomarker analysis and personalized recommendations for nutrition, exercise and supplements to optimize health and fitness, with the Terra assistant, an action plan and enterprise solutions.', 'InsideTracker допомагає вийти на пік форми тіла й розуму завдяки персональному плану, побудованому на всіх даних вашого організму. Сервіс аналізує біомаркери крові та формує науково обґрунтовані рекомендації щодо харчування, вправ і добавок, створені під ваші унікальні потреби, — замість загальних порад, що вимагають багато зусиль і дають мало результату. Ви отримуєте зрозумілі поради та план дій, а помічник Terra супроводжує вас і відповідає на запитання. Членство дозволяє регулярно відстежувати зміни показників і бачити ефект від змін у способі життя. Для компаній є окреме корпоративне рішення, а на сайті пояснюється, як це працює, і наукове підґрунтя.', 'InsideTracker helps you reach your strongest, healthiest body and mind with a personalized plan based on all your body''s data. The service analyzes blood biomarkers and creates science-backed recommendations for nutrition, exercise and supplements tailored to your unique needs — instead of generic advice that takes high effort for little impact. You get clear advice and an action plan, and the Terra assistant guides you and answers questions. Membership lets you track changes over time and see the effect of lifestyle changes. There is a separate enterprise solution, and the site explains how it works and the science behind it.', 'Аналіз біомаркерів крові
Персональні рекомендації щодо харчування й вправ
Рекомендації щодо добавок
Помічник Terra
Відстеження змін у часі
Рішення для компаній', 'Blood biomarker analysis
Personal nutrition and exercise advice
Supplement recommendations
Terra assistant
Tracking changes over time
Enterprise solution', 'Спортсмени-аматори й люди, які хочуть оптимізувати здоров''я та форму на основі даних.', 'Amateur athletes and people who want to optimize health and fitness with data.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
