INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Kubios HRV', NULL, 'https://www.kubios.com', NULL, NULL, 'Kubios HRV — програмне забезпечення для точного аналізу варіабельності серцевого ритму в науці, велнесі та спорті: Kubios HRV Scientific, Team Readiness для командних видів, застосунок і аналітика готовності.', 'Kubios HRV is software for accurate heart rate variability analysis in research, wellness and sports: Kubios HRV Scientific, Team Readiness for team sports, an app and readiness analytics.', 'Kubios спеціалізується на аналізі варіабельності серцевого ритму (ВСР) — фізіологічного явища, коли інтервали між ударами серця змінюються. ВСР використовують для оцінки відновлення, стресу та готовності до навантажень. Лінійка включає Kubios HRV Scientific і Scientific Lite для дослідників, Kubios HRV Team Readiness для командних видів спорту, мобільний Kubios HRV App і сервіси аналізу: аналітику готовності, аналітику спорту й навантажень та часову аналітику ВСР. Рішення розраховані на наукові дослідження, фізичні вправи й спорт, добробут і здоров''я, а також на велнес-фахівців. На сайті є блог про ВСР, відеоуроки, відповіді на запитання, новини й публікації.', 'Kubios specializes in heart rate variability (HRV) analysis — the physiological phenomenon where intervals between heartbeats vary. HRV is used to assess recovery, stress and readiness for training. The lineup includes Kubios HRV Scientific and Scientific Lite for researchers, Kubios HRV Team Readiness for team sports, the mobile Kubios HRV App and analysis services: readiness analytics, sport and exercise analytics and time-varying HRV analytics. Solutions serve scientific research, exercise and sports, wellbeing and health, and wellness professionals. The site has an HRV blog, video tutorials, FAQs, news and publications.', 'Точний аналіз ВСР
Kubios HRV Scientific для досліджень
Team Readiness для команд
Мобільний застосунок
Аналітика готовності й навантажень
