SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'movesense.com' OR LOWER(`name`) = LOWER('Movesense'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Movesense', NULL, 'https://www.movesense.com', NULL, NULL, 'Movesense — носимі сенсори для спорту й медицини: Movesense Sport і Movesense Medical вимірюють ЕКГ, пульс і рух, рішення CardioRTHM для моніторингу ЕКГ, OEM-послуги для компаній, що створюють власні продукти.', 'Movesense makes wearable sensors for sport and medicine: Movesense Sport and Movesense Medical measure ECG, heart rate and movement, CardioRTHM for ECG monitoring, and OEM services for companies building their own products.', 'Movesense — компанія медичних технологій, що постачає носимі пристрої та рішення для спортивних і медтех-компаній. Сенсор Movesense Sport вимірює рух і пульс і дозволяє розробникам створювати власні застосунки для аналізу тренувань і техніки. Movesense Medical — медичний носимий пристрій для вимірювання ЕКГ, пульсу й руху. CardioRTHM — рішення для короткострокового й тривалого моніторингу ЕКГ у клінічних і віддалених умовах, як для професіоналів, так і для приватних користувачів. Компанія також надає OEM-послуги, документацію, специфікації, наукові публікації та приклади готових рішень. Аксесуари й сенсори доступні в онлайн-магазині.', 'Movesense is a medical technology company providing wearable devices and solutions for sports and medtech companies. The Movesense Sport sensor measures movement and heart rate and lets developers build their own apps for training and technique analysis. Movesense Medical is a medical wearable for measuring ECG, heart rate and movement. CardioRTHM is a solution for short- and long-term ECG monitoring in clinical and remote settings, for professionals and individuals. The company also provides OEM services, documentation, specifications, publications and showcases. Accessories and sensors are sold in the online shop.', 'Сенсор Movesense Sport
Медичний сенсор ЕКГ
Рішення CardioRTHM
Платформа для власних застосунків
OEM-послуги', 'Movesense Sport sensor
Medical ECG sensor
CardioRTHM solution
Platform for custom apps
OEM services', 'Розробники спортивних застосунків, медтех-компанії та дослідники.', 'Sports app developers, medtech companies and researchers.', 'mobile', 'course', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
