-- Moxy Monitor — Моніторинг навантаження та відновлення
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'moxymonitor.com' OR LOWER(`name`) = LOWER('Moxy Monitor'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Moxy Monitor', NULL, 'https://www.moxymonitor.com', NULL, NULL, 'Moxy Monitor — невеликий носимий сенсор, що за допомогою інфрачервоного світла безперервно вимірює насичення м''язів киснем (SmO₂) під час тренування, допомагаючи точно контролювати інтенсивність; для спорту, науки й освіти.', 'Moxy Monitor is a small wearable sensor that uses infrared light to continuously measure muscle oxygen saturation (SmO₂) during exercise, helping control intensity precisely; for sport, research and education.', 'Moxy Monitor — компактний сенсор, що кріпиться на м''яз і за допомогою ближньої інфрачервоної спектроскопії (NIRS) у реальному часі вимірює насичення м''язової тканини киснем (SmO₂). Ці дані дозволяють точно контролювати інтенсивність тренувань і змагань, бачити, як м''язи реагують на навантаження, та ефективніше будувати інтервали й відновлення. За словами виробника, це науково валідований NIRS-пристрій для вимірювання SmO₂ в повному діапазоні від 0 до 100%, повністю неінвазивний. Рішення розраховані на спорт високих досягнень, дослідження та освіту, а на сайті пояснюється, як використовувати дані про кисень у м''язах для тренувань.', 'Moxy Monitor is a compact sensor that attaches over a muscle and uses near-infrared spectroscopy (NIRS) to measure muscle tissue oxygen saturation (SmO₂) in real time. These data let you precisely control training and race intensity, see how muscles respond to load and design intervals and recovery more effectively. According to the maker, it is a scientifically validated NIRS device for measuring SmO₂ across the full 0–100% range, and it is completely non-invasive. Solutions target high-performance sport, research and education, and the site explains how to use muscle oxygen data in training.', 'Вимірювання SmO₂ у реальному часі
Технологія NIRS
Контроль інтенсивності тренувань
Неінвазивний носимий сенсор
Для спорту, науки й освіти', 'Real-time SmO₂ measurement
NIRS technology
Training intensity control
Non-invasive wearable
For sport, research and education', 'Спортсмени на витривалість, тренери та спортивні науковці.', 'Endurance athletes, coaches and sports scientists.', 'mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
