-- Nix Biosensors — Моніторинг навантаження та відновлення
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'nixbiosensors.com' OR LOWER(`name`) = LOWER('Nix Biosensors'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Nix Biosensors', NULL, 'https://nixbiosensors.com', NULL, NULL, 'Nix — біосенсор гідратації, що аналізує піт і в реальному часі дає спортсменам на витривалість персональні рекомендації щодо пиття; Nix Solo для окремих атлетів, Nix Pro для груп і команд, патчі та набори.', 'Nix is a hydration biosensor that analyzes sweat and gives endurance athletes personalized real-time drinking guidance; Nix Solo for individuals, Nix Pro for groups and teams, patches and bundles.', 'Nix — перший біосенсор, що аналізує піт і надає спортсменам на витривалість персоналізовані дані про гідратацію в реальному часі, спираючись на науку й дані, для високих результатів і доброго самопочуття. Сенсор кріпиться на тіло за допомогою змінного патча й передає дані в застосунок, який підказує, скільки й коли пити та скільки електролітів ви втрачаєте. Nix Solo розрахований на окремих спортсменів, Nix Pro — на групи й команди, а Nix Health перебуває в розробці. На сайті є наукове обґрунтування, кейси, освітні матеріали про гідратацію, поради щодо застосунку, а в магазині — сенсор, запасні патчі, тренувальні набори й подарункові картки.', 'Nix is the first biosensor to analyze sweat and give endurance athletes personalized, real-time hydration intelligence grounded in science and data, for peak performance and wellbeing. The sensor attaches to the body with a replaceable patch and sends data to the app, which tells you how much and when to drink and how many electrolytes you lose. Nix Solo is for individual athletes, Nix Pro for groups and teams, and Nix Health is in development. The site has the science, case studies, hydration education and app tips, and the shop sells the sensor, refill patches, training bundles and gift cards.', 'Аналіз поту в реальному часі
Персональні рекомендації щодо пиття
Втрати електролітів
Nix Solo і Nix Pro
Змінні патчі', 'Real-time sweat analysis
Personal drinking guidance
Electrolyte losses
Nix Solo and Nix Pro
Replaceable patches', 'Бігуни, велосипедисти, тріатлоністи та команди.', 'Runners, cyclists, triathletes and teams.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
