SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'physitrack.com' OR LOWER(`name`) = LOWER('Physitrack'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Physitrack', NULL, 'https://www.physitrack.com', NULL, NULL, 'Physitrack — платформа віддаленої роботи з пацієнтами й телемедицини для фізіотерапевтів: конструктор домашніх програм вправ, застосунок для пацієнтів Physiapp, збір результатів, EMR і рішення для елітного спорту.', 'Physitrack is a remote patient engagement and telehealth platform for physiotherapists: a home exercise program builder, the Physiapp patient app, outcomes collection, EMR and solutions for elite sport.', 'Physitrack допомагає фізіотерапевтам і клінікам залучати пацієнтів, проводити телеконсультації та збирати дані про результати лікування в реальному часі. Конструктор домашніх програм вправ дозволяє швидко призначати відеовправи, а пацієнти виконують їх через застосунок Physiapp. Платформа включає віддалений терапевтичний моніторинг, електронну медичну карту, асистента PhysiAssistant, освітні модулі та e-learning. Рішення розраховані на приватні практики, охорону праці й ведення випадків, лікарні та системи охорони здоров''я, а також на елітний спорт, де фізіотерапія допомагає повертати атлетів до тренувань і підвищувати результати.', 'Physitrack helps physiotherapists and clinics engage patients, run telehealth consultations and collect real-time outcomes data. The home exercise program builder lets you quickly prescribe video exercises, and patients follow them in the Physiapp app. The platform includes remote therapeutic monitoring, an electronic medical record, PhysiAssistant, educational modules and e-learning. Solutions serve private practices, occupational health and case management, hospitals and healthcare systems, and elite sport, where physiotherapy helps athletes return to training and perform better.', 'Конструктор домашніх програм вправ
Застосунок для пацієнтів Physiapp
