Elite sports solutions', 'Фізіотерапевти, клініки, лікарні та медичні служби спортивних команд.', 'Physiotherapists, clinics, hospitals and sports team medical staff.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
