SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'sensoriafitness.com' OR LOWER(`name`) = LOWER('Sensoria'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Sensoria', NULL, 'https://www.sensoriafitness.com', NULL, NULL, 'Sensoria — розумний спортивний одяг і взуття з AI: тренувальний одяг із вбудованим вимірюванням пульсу, шкарпетки для аналізу бігу й персональний тренер у реальному часі, що допомагає покращити техніку.', 'Sensoria makes AI-powered smart sportswear and footwear: training apparel with built-in heart rate monitoring, running analysis and a real-time personal trainer that helps improve your form.', 'Sensoria створює спортивний одяг зі штучним інтелектом, що працює як персональний тренер у реальному часі. Тренувальний одяг із вбудованими технологіями вимірює пульс для ефективніших тренувань, а розумні рішення для бігу допомагають аналізувати техніку. Застосунки підходять для тих, хто ходить, бігає підтюпцем чи бігає серйозно: залежно від мети й рівня можна обрати активність і найважливіші метрики для відстеження. Компанія прагне допомогти покращити форму руху, результати й безпеку. Окрім спорту, Sensoria розвиває напрями взуття й охорони здоров''я, пропонує платформу для партнерів і кейси. Дані синхронізуються з телефоном.', 'Sensoria creates AI sportswear that works like a real-time personal trainer. Training apparel with embedded technology monitors heart rate for more effective workouts, and smart running solutions help analyze technique. The apps suit walkers, joggers and runners: depending on your goals and fitness level you choose the activity and the most relevant metrics to track. The company aims to help improve form, performance and safety. Beyond sport, Sensoria develops footwear and healthcare solutions and offers a partner platform and case studies. Data sync to the phone.', 'Одяг із вимірюванням пульсу
Аналіз бігової техніки
Персональний AI-тренер у реальному часі
Застосунки для ходьби й бігу
Платформа для партнерів', 'Apparel with heart rate monitoring
Running technique analysis
Real-time AI trainer
Apps for walking and running
Partner platform', 'Бігуни, любителі ходьби, а також партнери з охорони здоров''я.', 'Runners, walkers and healthcare partners.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
