-- Styku — Моніторинг навантаження та відновлення
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'styku.com' OR LOWER(`name`) = LOWER('Styku'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Styku', NULL, 'https://www.styku.com', NULL, NULL, 'Styku — екосистема 3D-сканування тіла для фітнесу, здоров''я й велнесу: 3D-сканери, аналітичне ПЗ Styku Studio, мобільний застосунок і Healthpass, що перетворює скан на профілактичний скринінг здоров''я.', 'Styku is a 3D body scanning ecosystem for fitness, health and wellness: 3D scanners, Styku Studio analytics software, a mobile app and Healthpass, which turns each scan into a preventive health screening.', 'Styku поєднує 3D-сканери тіла, аналітичне програмне забезпечення та мобільний застосунок в одну пов''язану екосистему. Скан фіксує форму та обхвати тіла й допомагає наочно бачити прогрес тренувань і харчування, що мотивує клієнтів. Програма Styku Studio аналізує дані, а нова функція Healthpass перетворює кожен скан на профілактичний скринінг здоров''я. Рішення використовують фітнес-клуби, медичні спа й естетичні клініки, дієтологи й програми керування вагою, функціональна медицина, охорона здоров''я, університети й дослідницькі центри. На сайті є блог, база знань, пошук сканера поруч, інформація про патенти, клієнтський портал і запис на демонстрацію.', 'Styku combines 3D body scanners, analytics software and a mobile app into one connected ecosystem. A scan captures body shape and measurements and helps clients see the progress of training and nutrition, which keeps them motivated. Styku Studio software analyzes the data, and the new Healthpass feature turns every scan into a preventive health screening. Solutions are used by fitness clubs, medspas and aesthetic clinics, dietitians and weight management programs, functional medicine, healthcare, universities and research centers. The site has a blog, a knowledge base, a local scanner finder, patents, a client portal and demo booking.', '3D-сканування тіла
Аналітика Styku Studio
Мобільний застосунок
Профілактичний скринінг Healthpass
Пошук сканера поруч', '3D body scanning
Styku Studio analytics
Mobile app
Healthpass preventive screening
Local scanner finder', 'Фітнес-клуби, клініки, дієтологи, дослідники та їхні клієнти.', 'Fitness clubs, clinics, dietitians, researchers and their clients.', 'desktop,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
