SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'train.red' OR LOWER(`name`) = LOWER('Train.Red'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Train.Red', NULL, 'https://train.red', NULL, NULL, 'Train.Red — сенсори кисню в м''язах Fyer 2.0 і Fyer 2.0 Pro, що дають інсайти про роботу м''язів під час тренування: для аматорів, атлетів, персональних тренерів, тренерів з продуктивності та спортивних науковців.', 'Train.Red makes Fyer 2.0 and Fyer 2.0 Pro muscle oxygen sensors that give insight into muscle performance during training, for enthusiasts, athletes, personal trainers, performance coaches and sports scientists.', 'Train.Red допомагає контролювати ріст продуктивності, показуючи, як працюють м''язи під час тренування. Сенсори кисню в м''язах вимірюють насичення м''язів киснем і передають дані в застосунок, щоб ви могли краще дозувати навантаження, точніше будувати інтервали й досягати кращих тренувальних результатів. Лінійка включає Fyer 2.0, Fyer 2.0 Pro, комплекти, оновлення та аксесуари — патчі й ремінці. Рішення адаптовані для атлетів, тренерів, спортивних лабораторій і команд. Перед покупкою можна пройти курс, а в освітньому розділі є блог, наукові публікації, опис технології та основи кисню в м''язах; можна поговорити з експертом.', 'Train.Red helps you control your performance growth by showing how your muscles work during training. Muscle oxygen sensors measure muscle oxygen saturation and send data to the app so you can dose load better, design intervals more precisely and get better training results. The lineup includes Fyer 2.0, Fyer 2.0 Pro, bundles, upgrades and accessories such as patches and straps. Solutions are tailored for athletes, coaches, sports labs and teams. Before buying you can take a course, and the education section offers a blog, publications, the technology and muscle oxygen basics; you can also talk to an expert.', 'Сенсори кисню в м''язах Fyer 2.0
Дані про роботу м''язів
Дозування навантаження
