INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Train.Red helps you control your performance growth by showing how your muscles work during training. Muscle oxygen sensors measure muscle oxygen saturation and send data to the app so you can dose load better, design intervals more precisely and get better training results. The lineup includes Fyer 2.0, Fyer 2.0 Pro, bundles, upgrades and accessories such as patches and straps. Solutions are tailored for athletes, coaches, sports labs and teams. Before buying you can take a course, and the education section offers a blog, publications, the technology and muscle oxygen basics; you can also talk to an expert.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'main_features', 'en', 'Fyer 2.0 muscle oxygen sensors
Muscle performance data
Load dosing
Team and lab solutions
Education course', 'manual' FROM DUAL WHERE @new = 1;
