SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'vo2master.com' OR LOWER(`name`) = LOWER('VO2 Master'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'VO2 Master', NULL, 'https://vo2master.com', NULL, NULL, 'VO2 Master — портативний бездротовий аналізатор VO2 і швидкості обміну в спокої для фітнесу, здоров''я, коучингу й досліджень: тестування від налаштування до миттєвого звіту, маски, фільтри, інтеграції й наукова валідація.', 'VO2 Master is a portable wireless VO2 and resting metabolic rate analyzer for fitness, health, coaching and research: testing from setup to instant report, masks, filters, integrations and scientific validation.', 'VO2 Master — канадський портативний метаболічний аналізатор, що вимірює споживання кисню (VO2) і швидкість обміну речовин у спокої (RMR) без стаціонарної лабораторії. Бездротовий пристрій дозволяє проводити тестування в залі, на треку чи у полі та отримувати звіт одразу після тесту. Дані допомагають точно визначати тренувальні зони, відстежувати прогрес і контролювати навантаження. На сайті покроково пояснюється процес тестування від першого налаштування до звітів, описано функції, аксесуари — різні маски, ремінці, змінні фільтри — і інтеграції з іншими сервісами. Окремий розділ присвячено валідації й дослідженням в академічних і реальних умовах.', 'VO2 Master is a Canadian portable metabolic analyzer that measures oxygen consumption (VO2) and resting metabolic rate (RMR) without a stationary lab. The wireless device lets you test in the gym, on the track or in the field and get a report immediately after the test. The data help define training zones precisely, track progress and control load. The site walks through the testing experience from first setup to reporting and describes features, accessories — multiple masks, straps and replacement filters — and integrations. A dedicated section covers validation and research in academic and real-world settings.', 'Портативне вимірювання VO2
Швидкість обміну в спокої
Бездротове тестування в полі
Миттєві звіти
Аксесуари й інтеграції
Наукова валідація', 'Portable VO2 measurement
Resting metabolic rate
Wireless field testing
Instant reports
Accessories and integrations
Scientific validation', 'Тренери з витривалості, фітнес-фахівці, клініки й дослідницькі команди.', 'Endurance coaches, fitness professionals, clinics and research teams.', 'mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
